// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0));
        amount = bound(amount, 1, type(uint256).max);

        vm.deal(sender, amount);

        uint256 before = c.depositsCount();

        vm.prank(sender);
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);

        uint256 afterCount = c.depositsCount();
        assertTrue(afterCount == before + 1);
    }
}
